#include <windows.h>
#include <stdio.h>
static double q(void){LARGE_INTEGER a,b;QueryPerformanceCounter(&a);QueryPerformanceFrequency(&b);return 1000.*a.QuadPart/b.QuadPart;}
int wmain(int argc,wchar_t**argv){if(argc!=2)return 2;wchar_t cmd[]=L"obit.exe hook claude";STARTUPINFOW si={sizeof(si)};PROCESS_INFORMATION pi={0};double start=q(),created=0,first=0,entry=0,last=0;int early=0,late=0; if(!CreateProcessW(argv[1],cmd,NULL,NULL,FALSE,DEBUG_ONLY_THIS_PROCESS|CREATE_NO_WINDOW,NULL,NULL,&si,&pi))return 3;created=q(); for(;;){DEBUG_EVENT d;if(!WaitForDebugEvent(&d,10000))return 4;DWORD cont=DBG_CONTINUE;double t=q();switch(d.dwDebugEventCode){case CREATE_PROCESS_DEBUG_EVENT:first=t;if(d.u.CreateProcessInfo.hFile)CloseHandle(d.u.CreateProcessInfo.hFile);break;case LOAD_DLL_DEBUG_EVENT:if(entry==0){early++;last=t;}else late++;if(d.u.LoadDll.hFile)CloseHandle(d.u.LoadDll.hFile);break;case EXCEPTION_DEBUG_EVENT:if(!entry && d.u.Exception.ExceptionRecord.ExceptionCode==EXCEPTION_BREAKPOINT)entry=t;else cont=DBG_EXCEPTION_NOT_HANDLED;break;}ContinueDebugEvent(d.dwProcessId,d.dwThreadId,cont);if(d.dwDebugEventCode==EXIT_PROCESS_DEBUG_EVENT)break;}printf("%.6f %.6f %.6f %d %d\n",created-start,entry-first,last-first,early,late);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);return 0;}
